additionalExercises.referenceSolution:
#include <iostream>
#include <stdexcept>
#include <string>

int main() {
    std::string word;
    while (std::cin >> word) {
        try {
            std::size_t pos;
            int value = std::stoi(word, &pos);
            if (pos != word.size()) {
                std::cout << "лишние символы\n";
            } else {
                std::cout << "число " << value << '\n';
            }
        } catch (const std::invalid_argument &) {
            std::cout << "не число\n";
        } catch (const std::out_of_range &) {
            std::cout << "слишком большое\n";
        }
    }
    return 0;
}

